-- Projects library: preserve custom drafts, SEO, unpublished entries and existing URLs.
-- Field replacements require both versions to match the original starter value. JSON text is CRLF-safe.

UPDATE content_items SET draft_json=json_set(draft_json,'$.title',json_extract('{"v":"Halo-Lit Reception Logo"}','$.v')),published_json=json_set(published_json,'$.title',json_extract('{"v":"Halo-Lit Reception Logo"}','$.v')),version=version+1 WHERE type='project' AND slug='office-logo-concept' AND status='published' AND json_extract(draft_json,'$.title')=json_extract('{"v":"Office Logo Sign"}','$.v') AND json_extract(published_json,'$.title')=json_extract('{"v":"Office Logo Sign"}','$.v');
UPDATE content_items SET draft_json=json_set(draft_json,'$.intro',json_extract('{"v":"A warm halo and a restrained metal finish bring a clear focal point to the reception wall."}','$.v')),published_json=json_set(published_json,'$.intro',json_extract('{"v":"A warm halo and a restrained metal finish bring a clear focal point to the reception wall."}','$.v')),version=version+1 WHERE type='project' AND slug='office-logo-concept' AND status='published' AND json_extract(draft_json,'$.intro')=json_extract('{"v":"Backlit lettering in a reception setting."}','$.v') AND json_extract(published_json,'$.intro')=json_extract('{"v":"Backlit lettering in a reception setting."}','$.v');
UPDATE content_items SET draft_json=json_set(draft_json,'$.body',json_extract('{"v":"## The Design Brief\n\nCreate a recognisable arrival point without overpowering the interior. This reception concept pairs a dimensional logo with soft rear illumination, leaving space around the mark so it reads clearly from the entrance.\n\n## Design Decisions\n\n### Light behind the logo\n\nRear illumination outlines the lettering while keeping the faces visually calm. Wall texture and stand-off distance affect how the halo spreads.\n\n### Finish in conversation with the space\n\nA warm metal appearance works with stone and timber. The final metal, surface treatment and colour reference are selected for your brand.\n\n### Scale around the reception desk\n\nUse the desk width, wall area and entrance sightline to set the overall logo width and position. A wall photograph is more useful than a letter height alone.\n\n## Proposed Configuration\n\n**Application:** Office and reception feature wall\n\n**Letter construction:** Opaque metal face and formed returns; construction to be specified\n\n**Lighting direction:** Rear LED illumination; warm or neutral white to be reviewed\n\n**Finish:** Brushed, painted or plated appearance by approved reference\n\n**Mounting approach:** Stand-off fixing with a planned cable route behind the sign\n\n**Size & scope:** Made to your artwork; dimensions, components and installation scope quoted individually\n\n## Prepare Your Installation\n\n### Check the wall\n\nSend a straight-on photo, available width and height, and wall material. Uneven or reflective finishes can change the halo.\n\n### Plan power and access\n\nIdentify the cable exit, driver location and maintenance access with your installer before the wall is closed.\n\n### Review the visual proof\n\nConfirm logo spacing, wall clearance, light colour and the sign position on your wall drawing before production.\n\n## Make It Your Own\n\nReplace the mark and lettering with your own vector artwork. Adjust the overall scale, metal finish and light colour to suit the space.\n\nFor multiple reception locations, share a wall photo and dimensions for each site so the same visual direction can be adapted consistently."}','$.v')),published_json=json_set(published_json,'$.body',json_extract('{"v":"## The Design Brief\n\nCreate a recognisable arrival point without overpowering the interior. This reception concept pairs a dimensional logo with soft rear illumination, leaving space around the mark so it reads clearly from the entrance.\n\n## Design Decisions\n\n### Light behind the logo\n\nRear illumination outlines the lettering while keeping the faces visually calm. Wall texture and stand-off distance affect how the halo spreads.\n\n### Finish in conversation with the space\n\nA warm metal appearance works with stone and timber. The final metal, surface treatment and colour reference are selected for your brand.\n\n### Scale around the reception desk\n\nUse the desk width, wall area and entrance sightline to set the overall logo width and position. A wall photograph is more useful than a letter height alone.\n\n## Proposed Configuration\n\n**Application:** Office and reception feature wall\n\n**Letter construction:** Opaque metal face and formed returns; construction to be specified\n\n**Lighting direction:** Rear LED illumination; warm or neutral white to be reviewed\n\n**Finish:** Brushed, painted or plated appearance by approved reference\n\n**Mounting approach:** Stand-off fixing with a planned cable route behind the sign\n\n**Size & scope:** Made to your artwork; dimensions, components and installation scope quoted individually\n\n## Prepare Your Installation\n\n### Check the wall\n\nSend a straight-on photo, available width and height, and wall material. Uneven or reflective finishes can change the halo.\n\n### Plan power and access\n\nIdentify the cable exit, driver location and maintenance access with your installer before the wall is closed.\n\n### Review the visual proof\n\nConfirm logo spacing, wall clearance, light colour and the sign position on your wall drawing before production.\n\n## Make It Your Own\n\nReplace the mark and lettering with your own vector artwork. Adjust the overall scale, metal finish and light colour to suit the space.\n\nFor multiple reception locations, share a wall photo and dimensions for each site so the same visual direction can be adapted consistently."}','$.v')),version=version+1 WHERE type='project' AND slug='office-logo-concept' AND status='published' AND replace(json_extract(draft_json,'$.body'),char(13),'')=json_extract('{"v":"## The Design Brief\n\nThis illustrative concept explores a backlit logo as a focal point behind a reception desk. It is a visual starting point, not a completed client installation or a supplied construction drawing.\n\n## What to Review for Your Space\n\nCompare the logo scale with the reception wall, the visible face finish and the halo behind the letters. Wall colour, texture, mounting distance and room lighting can change the result. Send a wider photograph and approximate wall measurements with your artwork.\n\n## Turn the Direction into Your Own Specification\n\nReview overall dimensions, individual shapes, face and side finish, light colour, fixing method, cable route and access. Any required documents and the local installer''s responsibilities must be agreed before the design is approved for production."}','$.v') AND replace(json_extract(published_json,'$.body'),char(13),'')=json_extract('{"v":"## The Design Brief\n\nThis illustrative concept explores a backlit logo as a focal point behind a reception desk. It is a visual starting point, not a completed client installation or a supplied construction drawing.\n\n## What to Review for Your Space\n\nCompare the logo scale with the reception wall, the visible face finish and the halo behind the letters. Wall colour, texture, mounting distance and room lighting can change the result. Send a wider photograph and approximate wall measurements with your artwork.\n\n## Turn the Direction into Your Own Specification\n\nReview overall dimensions, individual shapes, face and side finish, light colour, fixing method, cable route and access. Any required documents and the local installer''s responsibilities must be agreed before the design is approved for production."}','$.v');
UPDATE content_items SET draft_json=json_set(draft_json,'$.image',json_extract('{"v":"/assets/home-v2/scene-reception.webp"}','$.v')),published_json=json_set(published_json,'$.image',json_extract('{"v":"/assets/home-v2/scene-reception.webp"}','$.v')),version=version+1 WHERE type='project' AND slug='office-logo-concept' AND status='published' AND json_extract(draft_json,'$.image')=json_extract('{"v":"/assets/office-halo.webp"}','$.v') AND json_extract(published_json,'$.image')=json_extract('{"v":"/assets/office-halo.webp"}','$.v');
