UPDATE content_items SET draft_json=json_set(draft_json,'$.gallery',json(json_extract('{"v":[{"src":"/assets/products-v2/halo-face.webp","alt":"Opaque gold-tone letter face with rear illumination","caption":"Design reference · Opaque face with warm rear halo"},{"src":"/assets/supplier/halo-letter-samples.webp","alt":"Illuminated metal letter samples on a work surface","caption":"Fabrication sample · Compare face, return and illuminated backing"}]}','$.v'))),published_json=json_set(published_json,'$.gallery',json(json_extract('{"v":[{"src":"/assets/products-v2/halo-face.webp","alt":"Opaque gold-tone letter face with rear illumination","caption":"Design reference · Opaque face with warm rear halo"},{"src":"/assets/supplier/halo-letter-samples.webp","alt":"Illuminated metal letter samples on a work surface","caption":"Fabrication sample · Compare face, return and illuminated backing"}]}','$.v'))),version=version+1 WHERE type='project' AND slug='office-logo-concept' AND status='published' AND json_extract(draft_json,'$.gallery')=json_extract('{"v":[{"src":"/assets/supplier/halo-letter-samples.webp","alt":"Individual illuminated letters from the supplier brochure","caption":"Supplier reference — individual letter samples with rear illumination."}]}','$.v') AND json_extract(published_json,'$.gallery')=json_extract('{"v":[{"src":"/assets/supplier/halo-letter-samples.webp","alt":"Individual illuminated letters from the supplier brochure","caption":"Supplier reference — individual letter samples with rear illumination."}]}','$.v');

UPDATE content_items SET draft_json=json_set(draft_json,'$.title',json_extract('{"v":"Front-Lit Storefront Lettering"}','$.v')),published_json=json_set(published_json,'$.title',json_extract('{"v":"Front-Lit Storefront Lettering"}','$.v')),version=version+1 WHERE type='project' AND slug='storefront-concept' AND status='published' AND json_extract(draft_json,'$.title')=json_extract('{"v":"Storefront Sign"}','$.v') AND json_extract(published_json,'$.title')=json_extract('{"v":"Storefront Sign"}','$.v');
UPDATE content_items SET draft_json=json_set(draft_json,'$.intro',json_extract('{"v":"Individual illuminated letters give the shopfront a defined identity across daytime and evening views."}','$.v')),published_json=json_set(published_json,'$.intro',json_extract('{"v":"Individual illuminated letters give the shopfront a defined identity across daytime and evening views."}','$.v')),version=version+1 WHERE type='project' AND slug='storefront-concept' AND status='published' AND json_extract(draft_json,'$.intro')=json_extract('{"v":"Illuminated lettering on a commercial facade."}','$.v') AND json_extract(published_json,'$.intro')=json_extract('{"v":"Illuminated lettering on a commercial facade."}','$.v');
UPDATE content_items SET draft_json=json_set(draft_json,'$.body',json_extract('{"v":"## The Design Brief\n\nMake the business name easy to identify above the entrance. This storefront concept uses individual illuminated letters on a dark fascia, with generous spacing and a clear relationship to the door and glazing below.\n\n## Design Decisions\n\n### A clear illuminated face\n\nThe face carries the light, helping the lettering stand apart from the darker fascia. Brightness and colour need to suit the surroundings.\n\n### Letters that fit the frontage\n\nThe sign sits within the architectural band rather than filling every available edge. Review viewing distance and landlord restrictions when setting the size.\n\n### Concealed details\n\nFixings and cable routes should be planned with the fascia construction. Discuss individual mounting or a carrier where access is limited.\n\n## Proposed Configuration\n\n**Application:** Shopfront or commercial fascia\n\n**Letter construction:** Light-transmitting face with formed returns; material to be agreed\n\n**Lighting direction:** Front-facing LED illumination\n\n**Finish:** Face colour and return finish matched to an approved reference\n\n**Mounting approach:** Individual fixings or a carrier, selected for the fascia\n\n**Size & scope:** Logo, overall width and quantities confirmed from your frontage measurements\n\n## Prepare Your Installation\n\n### Survey the fascia\n\nProvide the sign area, surface material, viewing distance and a straight-on site photo.\n\n### Confirm site requirements\n\nIdentify property approvals, local sign rules and destination electrical requirements with the responsible local team.\n\n### Coordinate the connection\n\nPlan cable penetrations, driver access and weather exposure before fabrication and local installation.\n\n## Make It Your Own\n\nUse your own logotype and colour palette. Compare face illumination, letter depth and return finish against the façade.\n\nFor more than one shop, identify the quantities, sign sizes and destination for each location in your enquiry."}','$.v')),published_json=json_set(published_json,'$.body',json_extract('{"v":"## The Design Brief\n\nMake the business name easy to identify above the entrance. This storefront concept uses individual illuminated letters on a dark fascia, with generous spacing and a clear relationship to the door and glazing below.\n\n## Design Decisions\n\n### A clear illuminated face\n\nThe face carries the light, helping the lettering stand apart from the darker fascia. Brightness and colour need to suit the surroundings.\n\n### Letters that fit the frontage\n\nThe sign sits within the architectural band rather than filling every available edge. Review viewing distance and landlord restrictions when setting the size.\n\n### Concealed details\n\nFixings and cable routes should be planned with the fascia construction. Discuss individual mounting or a carrier where access is limited.\n\n## Proposed Configuration\n\n**Application:** Shopfront or commercial fascia\n\n**Letter construction:** Light-transmitting face with formed returns; material to be agreed\n\n**Lighting direction:** Front-facing LED illumination\n\n**Finish:** Face colour and return finish matched to an approved reference\n\n**Mounting approach:** Individual fixings or a carrier, selected for the fascia\n\n**Size & scope:** Logo, overall width and quantities confirmed from your frontage measurements\n\n## Prepare Your Installation\n\n### Survey the fascia\n\nProvide the sign area, surface material, viewing distance and a straight-on site photo.\n\n### Confirm site requirements\n\nIdentify property approvals, local sign rules and destination electrical requirements with the responsible local team.\n\n### Coordinate the connection\n\nPlan cable penetrations, driver access and weather exposure before fabrication and local installation.\n\n## Make It Your Own\n\nUse your own logotype and colour palette. Compare face illumination, letter depth and return finish against the façade.\n\nFor more than one shop, identify the quantities, sign sizes and destination for each location in your enquiry."}','$.v')),version=version+1 WHERE type='project' AND slug='storefront-concept' AND status='published' AND replace(json_extract(draft_json,'$.body'),char(13),'')=json_extract('{"v":"## The Design Brief\n\nThis illustrative concept explores illuminated lettering on a commercial facade. No customer, location or completed delivery is claimed. It helps describe the visibility and character you want for your own business frontage.\n\n## What to Review for Your Facade\n\nConsider the sign area, viewing distance, existing surface, surrounding light and access for installation. Send your own logo, a straight-on location photo and approximate measurements. Any property or local approval requirements need to be identified by the parties responsible for the site.\n\n## Confirm the Construction Separately\n\nDiscuss the proposed face, returns, depth, finish, lighting and mounting rather than assuming the illustration defines them. Destination requirements, supplied components, shipping and local installation responsibilities are part of the project review."}','$.v') AND replace(json_extract(published_json,'$.body'),char(13),'')=json_extract('{"v":"## The Design Brief\n\nThis illustrative concept explores illuminated lettering on a commercial facade. No customer, location or completed delivery is claimed. It helps describe the visibility and character you want for your own business frontage.\n\n## What to Review for Your Facade\n\nConsider the sign area, viewing distance, existing surface, surrounding light and access for installation. Send your own logo, a straight-on location photo and approximate measurements. Any property or local approval requirements need to be identified by the parties responsible for the site.\n\n## Confirm the Construction Separately\n\nDiscuss the proposed face, returns, depth, finish, lighting and mounting rather than assuming the illustration defines them. Destination requirements, supplied components, shipping and local installation responsibilities are part of the project review."}','$.v');
UPDATE content_items SET draft_json=json_set(draft_json,'$.image',json_extract('{"v":"/assets/home-v2/scene-storefront.webp"}','$.v')),published_json=json_set(published_json,'$.image',json_extract('{"v":"/assets/home-v2/scene-storefront.webp"}','$.v')),version=version+1 WHERE type='project' AND slug='storefront-concept' AND status='published' AND json_extract(draft_json,'$.image')=json_extract('{"v":"/assets/storefront-wide.webp"}','$.v') AND json_extract(published_json,'$.image')=json_extract('{"v":"/assets/storefront-wide.webp"}','$.v');
