UPDATE content_items SET draft_json=json_set(draft_json,'$.gallery',json(json_extract('{"v":[{"src":"/assets/supplier/letter-face-reference.webp","alt":"Letter face and metal return shown unlit","caption":"Fabrication sample · Face, outline and return construction"},{"src":"/assets/supplier/led-layout-reference.webp","alt":"LED modules installed inside a letter","caption":"Construction detail · Internal LED layout to discuss for your design"}]}','$.v'))),published_json=json_set(published_json,'$.gallery',json(json_extract('{"v":[{"src":"/assets/supplier/letter-face-reference.webp","alt":"Letter face and metal return shown unlit","caption":"Fabrication sample · Face, outline and return construction"},{"src":"/assets/supplier/led-layout-reference.webp","alt":"LED modules installed inside a letter","caption":"Construction detail · Internal LED layout to discuss for your design"}]}','$.v'))),version=version+1 WHERE type='project' AND slug='storefront-concept' AND status='published' AND json_extract(draft_json,'$.gallery')=json_extract('{"v":[{"src":"/assets/supplier/letter-face-reference.webp","alt":"Unlit letter face and metal return from the supplier brochure","caption":"Supplier reference — unlit face and return reference."}]}','$.v') AND json_extract(published_json,'$.gallery')=json_extract('{"v":[{"src":"/assets/supplier/letter-face-reference.webp","alt":"Unlit letter face and metal return from the supplier brochure","caption":"Supplier reference — unlit face and return reference."}]}','$.v');

INSERT INTO content_items(id,type,slug,status,draft_json,published_json,sort_order) SELECT 'project-hospitality-metal-concept','project','hospitality-metal-concept','published','{"title":"Architectural Metal Entrance Sign","intro":"Dimensional metal lettering adds definition to a hospitality entrance through material and shadow.","product":"metal-letters","setting":"Hospitality","image":"/assets/home-v2/scene-hospitality.webp","imageAlt":"Architectural Metal Entrance Sign — AI-generated design concept","imageKind":"concept","sourceNote":"AI-generated design concept; not a delivered client installation. Existing licensed asset provenance is recorded in the homepage/product asset ledgers.","indexable":false,"sort":2,"gallery":[{"src":"/assets/supplier/formed-metal-letters.webp","alt":"Formed dimensional metal letters with a brushed finish","caption":"Fabrication sample · Brushed surface and dimensional depth"},{"src":"/assets/supplier/letter-edge-section.webp","alt":"Close view of a metal face and formed side","caption":"Construction detail · Face edge and return transition"}],"body":"## The Design Brief\n\nGive a hospitality entrance an understated identity that belongs to the architecture. This concept uses unlit dimensional lettering, with the material finish and surrounding ambient light doing the visual work.\n\n## Design Decisions\n\n### Material takes the lead\n\nA warm brushed-metal appearance creates contrast against the entrance surface. Discuss real finish references rather than relying on a screen colour.\n\n### Depth without integral lighting\n\nRaised lettering casts a changing shadow. Return depth and fixing position need to be balanced with logo size and the viewing angle.\n\n### Room around the identity\n\nThe name remains one considered element of the entrance. Align the sign with door, cladding and architectural features.\n\n## Proposed Configuration\n\n**Application:** Hotel, hospitality or commercial entrance\n\n**Letter construction:** Cut or built-up metal, selected to suit the artwork and required depth\n\n**Lighting direction:** Unlit lettering; appearance depends on daylight and site lighting\n\n**Finish:** Brushed, painted or plated surface, subject to finish approval\n\n**Mounting approach:** Stud fixing or a backing arrangement suitable for the substrate\n\n**Size & scope:** Overall width, depth, metal grade and exposed environment to be confirmed\n\n## Prepare Your Installation\n\n### Identify exposure\n\nTell us whether the location is sheltered, fully outdoors or near the coast. This informs the material and finish review.\n\n### Check the substrate\n\nProvide cladding and wall details so your installer can plan suitable fixings and access.\n\n### Review the light\n\nInclude a day and evening site photo. Unlit lettering depends on the lighting already available at the entrance.\n\n## Make It Your Own\n\nChange the font, symbol, metal appearance and dimensional depth. Share a physical or photographed finish reference where colour matching is important.\n\nCoordinate entrance lettering with room, floor or directional signs by including a schedule of the additional items."}','{"title":"Architectural Metal Entrance Sign","intro":"Dimensional metal lettering adds definition to a hospitality entrance through material and shadow.","product":"metal-letters","setting":"Hospitality","image":"/assets/home-v2/scene-hospitality.webp","imageAlt":"Architectural Metal Entrance Sign — AI-generated design concept","imageKind":"concept","sourceNote":"AI-generated design concept; not a delivered client installation. Existing licensed asset provenance is recorded in the homepage/product asset ledgers.","indexable":false,"sort":2,"gallery":[{"src":"/assets/supplier/formed-metal-letters.webp","alt":"Formed dimensional metal letters with a brushed finish","caption":"Fabrication sample · Brushed surface and dimensional depth"},{"src":"/assets/supplier/letter-edge-section.webp","alt":"Close view of a metal face and formed side","caption":"Construction detail · Face edge and return transition"}],"body":"## The Design Brief\n\nGive a hospitality entrance an understated identity that belongs to the architecture. This concept uses unlit dimensional lettering, with the material finish and surrounding ambient light doing the visual work.\n\n## Design Decisions\n\n### Material takes the lead\n\nA warm brushed-metal appearance creates contrast against the entrance surface. Discuss real finish references rather than relying on a screen colour.\n\n### Depth without integral lighting\n\nRaised lettering casts a changing shadow. Return depth and fixing position need to be balanced with logo size and the viewing angle.\n\n### Room around the identity\n\nThe name remains one considered element of the entrance. Align the sign with door, cladding and architectural features.\n\n## Proposed Configuration\n\n**Application:** Hotel, hospitality or commercial entrance\n\n**Letter construction:** Cut or built-up metal, selected to suit the artwork and required depth\n\n**Lighting direction:** Unlit lettering; appearance depends on daylight and site lighting\n\n**Finish:** Brushed, painted or plated surface, subject to finish approval\n\n**Mounting approach:** Stud fixing or a backing arrangement suitable for the substrate\n\n**Size & scope:** Overall width, depth, metal grade and exposed environment to be confirmed\n\n## Prepare Your Installation\n\n### Identify exposure\n\nTell us whether the location is sheltered, fully outdoors or near the coast. This informs the material and finish review.\n\n### Check the substrate\n\nProvide cladding and wall details so your installer can plan suitable fixings and access.\n\n### Review the light\n\nInclude a day and evening site photo. Unlit lettering depends on the lighting already available at the entrance.\n\n## Make It Your Own\n\nChange the font, symbol, metal appearance and dimensional depth. Share a physical or photographed finish reference where colour matching is important.\n\nCoordinate entrance lettering with room, floor or directional signs by including a schedule of the additional items."}',2 WHERE NOT EXISTS(SELECT 1 FROM content_items WHERE type='project' AND slug='hospitality-metal-concept');

INSERT INTO content_items(id,type,slug,status,draft_json,published_json,sort_order) SELECT 'project-acrylic-reception-concept','project','acrylic-reception-concept','published','{"title":"Colour-Led Reception Lettering","intro":"Bold dimensional lettering turns a simple interior wall into a recognisable brand touchpoint.","product":"acrylic-letters","setting":"Office","image":"/assets/products-v2/acrylic-scene.webp","imageAlt":"Colour-Led Reception Lettering — AI-generated design concept","imageKind":"concept","sourceNote":"AI-generated design concept; not a delivered client installation. Existing licensed asset provenance is recorded in the homepage/product asset ledgers.","indexable":false,"sort":3,"gallery":[{"src":"/assets/products-v2/acrylic-edge.webp","alt":"Close view of the edge of dimensional acrylic lettering","caption":"AI-generated detail reference · Acrylic depth and edge appearance"},{"src":"/assets/supplier/layered-acrylic-letter.webp","alt":"Layered coloured and clear acrylic letter sample","caption":"Fabrication sample · Layered acrylic construction"}],"body":"## The Design Brief\n\nBring a brand colour into a bright reception space. The concept uses solid-looking dimensional lettering with a clean outline, relying on colour contrast and depth rather than integral lighting.\n\n## Design Decisions\n\n### Brand colour as the focal point\n\nA saturated colour reads against the pale wall. Confirm the colour reference and whether a painted or material colour is required.\n\n### A simple dimensional silhouette\n\nThe artwork should retain clear strokes at the selected size. Review small counters and fine details before agreeing the fabrication approach.\n\n### Daylight and shadow\n\nUnlit lettering uses the room light to reveal depth. The wall and furniture establish the scale of the mark.\n\n## Proposed Configuration\n\n**Application:** Office, studio or reception brand wall\n\n**Letter construction:** Cut or layered acrylic; thickness and assembly to be reviewed\n\n**Lighting direction:** Unlit construction in this concept\n\n**Finish:** Solid colour, surface sheen and edge finish by approved reference\n\n**Mounting approach:** Stud, adhesive or backing option selected for the wall and letter size\n\n**Size & scope:** Artwork, available wall area and letter thickness confirmed before production\n\n## Prepare Your Installation\n\n### Measure the usable wall\n\nShare the wall width and height with any sockets, furniture or features that constrain the layout.\n\n### Discuss fixing limits\n\nTell us if drilling is restricted. Your installer should confirm the surface and suitable attachment method.\n\n### Approve colour and outline\n\nSend vector artwork and a colour reference. Review cut details and any proposed layering before fabrication.\n\n## Make It Your Own\n\nAdapt the logo, letter colour, thickness and surface sheen. Layer different colours or add a backing panel if required by the design.\n\nIf you want illumination, request it explicitly so the material and assembly can be reviewed for that different construction."}','{"title":"Colour-Led Reception Lettering","intro":"Bold dimensional lettering turns a simple interior wall into a recognisable brand touchpoint.","product":"acrylic-letters","setting":"Office","image":"/assets/products-v2/acrylic-scene.webp","imageAlt":"Colour-Led Reception Lettering — AI-generated design concept","imageKind":"concept","sourceNote":"AI-generated design concept; not a delivered client installation. Existing licensed asset provenance is recorded in the homepage/product asset ledgers.","indexable":false,"sort":3,"gallery":[{"src":"/assets/products-v2/acrylic-edge.webp","alt":"Close view of the edge of dimensional acrylic lettering","caption":"AI-generated detail reference · Acrylic depth and edge appearance"},{"src":"/assets/supplier/layered-acrylic-letter.webp","alt":"Layered coloured and clear acrylic letter sample","caption":"Fabrication sample · Layered acrylic construction"}],"body":"## The Design Brief\n\nBring a brand colour into a bright reception space. The concept uses solid-looking dimensional lettering with a clean outline, relying on colour contrast and depth rather than integral lighting.\n\n## Design Decisions\n\n### Brand colour as the focal point\n\nA saturated colour reads against the pale wall. Confirm the colour reference and whether a painted or material colour is required.\n\n### A simple dimensional silhouette\n\nThe artwork should retain clear strokes at the selected size. Review small counters and fine details before agreeing the fabrication approach.\n\n### Daylight and shadow\n\nUnlit lettering uses the room light to reveal depth. The wall and furniture establish the scale of the mark.\n\n## Proposed Configuration\n\n**Application:** Office, studio or reception brand wall\n\n**Letter construction:** Cut or layered acrylic; thickness and assembly to be reviewed\n\n**Lighting direction:** Unlit construction in this concept\n\n**Finish:** Solid colour, surface sheen and edge finish by approved reference\n\n**Mounting approach:** Stud, adhesive or backing option selected for the wall and letter size\n\n**Size & scope:** Artwork, available wall area and letter thickness confirmed before production\n\n## Prepare Your Installation\n\n### Measure the usable wall\n\nShare the wall width and height with any sockets, furniture or features that constrain the layout.\n\n### Discuss fixing limits\n\nTell us if drilling is restricted. Your installer should confirm the surface and suitable attachment method.\n\n### Approve colour and outline\n\nSend vector artwork and a colour reference. Review cut details and any proposed layering before fabrication.\n\n## Make It Your Own\n\nAdapt the logo, letter colour, thickness and surface sheen. Layer different colours or add a backing panel if required by the design.\n\nIf you want illumination, request it explicitly so the material and assembly can be reviewed for that different construction."}',3 WHERE NOT EXISTS(SELECT 1 FROM content_items WHERE type='project' AND slug='acrylic-reception-concept');

INSERT INTO content_items(id,type,slug,status,draft_json,published_json,sort_order) SELECT 'project-cafe-neon-concept','project','cafe-neon-concept','published','{"title":"Neon-Style Café Window Sign","intro":"A continuous illuminated line creates an inviting focal point in a café window.","product":"lightbox-neon","setting":"Dining","image":"/assets/products-v2/neon-scene.webp","imageAlt":"Neon-Style Café Window Sign — AI-generated design concept","imageKind":"concept","sourceNote":"AI-generated design concept; not a delivered client installation. Existing licensed asset provenance is recorded in the homepage/product asset ledgers.","indexable":false,"sort":4,"gallery":[{"src":"/assets/supplier/neon-style-signs.webp","alt":"Illuminated line graphic samples","caption":"Fabrication sample · Line graphics and lighting direction"},{"src":"/assets/products-v2/lightbox-scene.webp","alt":"Round projecting lightbox at a storefront","caption":"Alternative design concept · A projecting lightbox for a different viewing direction"}],"body":"## The Design Brief\n\nCreate a warm window accent that can be seen from the pavement while preserving the view into the café. This concept uses script-style illuminated lines on a clear backing, positioned above the customer seating area.\n\n## Design Decisions\n\n### A continuous line of light\n\nA line-based word or logo suits a neon-style approach. Tight bends, small lettering and stroke spacing need a construction review.\n\n### A backing that stays quiet\n\nA clear backing keeps the window visually open. Discuss its outline, visible fixing points and how the cable will leave the sign.\n\n### Place it within the window\n\nBalance the sign with the glazing, reflections and customer sightlines. The concept is an interior window application.\n\n## Proposed Configuration\n\n**Application:** Interior café, restaurant or shop window\n\n**Sign construction:** Neon-style LED line on a backing; exact system to be agreed\n\n**Lighting direction:** Visible illuminated line; light colour and control options to discuss\n\n**Backing:** Clear, shaped or coloured panel by approved drawing\n\n**Mounting approach:** Hanging or fixed arrangement suited to the window area\n\n**Size & scope:** Overall size, minimum detail, cable exit and power arrangement quoted for your artwork\n\n## Prepare Your Installation\n\n### Record the window dimensions\n\nInclude the clear opening, mullions and the position where the sign can hang or fix.\n\n### Plan the supply cable\n\nIdentify a power point, cable route and accessible power-supply position. Avoid assuming the illustration defines the electrical scope.\n\n### Review the artwork\n\nSend your wording or vector logo and preferred light colour. We review line paths, bends and backing shape before approval.\n\n## Make It Your Own\n\nReplace the wording with your own message or logo. Explore light colours, backing shapes and the arrangement of separate illuminated sections.\n\nFor a projecting lightbox or outdoor location, specify the different application so the enclosure, fixing and exposure can be reviewed."}','{"title":"Neon-Style Café Window Sign","intro":"A continuous illuminated line creates an inviting focal point in a café window.","product":"lightbox-neon","setting":"Dining","image":"/assets/products-v2/neon-scene.webp","imageAlt":"Neon-Style Café Window Sign — AI-generated design concept","imageKind":"concept","sourceNote":"AI-generated design concept; not a delivered client installation. Existing licensed asset provenance is recorded in the homepage/product asset ledgers.","indexable":false,"sort":4,"gallery":[{"src":"/assets/supplier/neon-style-signs.webp","alt":"Illuminated line graphic samples","caption":"Fabrication sample · Line graphics and lighting direction"},{"src":"/assets/products-v2/lightbox-scene.webp","alt":"Round projecting lightbox at a storefront","caption":"Alternative design concept · A projecting lightbox for a different viewing direction"}],"body":"## The Design Brief\n\nCreate a warm window accent that can be seen from the pavement while preserving the view into the café. This concept uses script-style illuminated lines on a clear backing, positioned above the customer seating area.\n\n## Design Decisions\n\n### A continuous line of light\n\nA line-based word or logo suits a neon-style approach. Tight bends, small lettering and stroke spacing need a construction review.\n\n### A backing that stays quiet\n\nA clear backing keeps the window visually open. Discuss its outline, visible fixing points and how the cable will leave the sign.\n\n### Place it within the window\n\nBalance the sign with the glazing, reflections and customer sightlines. The concept is an interior window application.\n\n## Proposed Configuration\n\n**Application:** Interior café, restaurant or shop window\n\n**Sign construction:** Neon-style LED line on a backing; exact system to be agreed\n\n**Lighting direction:** Visible illuminated line; light colour and control options to discuss\n\n**Backing:** Clear, shaped or coloured panel by approved drawing\n\n**Mounting approach:** Hanging or fixed arrangement suited to the window area\n\n**Size & scope:** Overall size, minimum detail, cable exit and power arrangement quoted for your artwork\n\n## Prepare Your Installation\n\n### Record the window dimensions\n\nInclude the clear opening, mullions and the position where the sign can hang or fix.\n\n### Plan the supply cable\n\nIdentify a power point, cable route and accessible power-supply position. Avoid assuming the illustration defines the electrical scope.\n\n### Review the artwork\n\nSend your wording or vector logo and preferred light colour. We review line paths, bends and backing shape before approval.\n\n## Make It Your Own\n\nReplace the wording with your own message or logo. Explore light colours, backing shapes and the arrangement of separate illuminated sections.\n\nFor a projecting lightbox or outdoor location, specify the different application so the enclosure, fixing and exposure can be reviewed."}',4 WHERE NOT EXISTS(SELECT 1 FROM content_items WHERE type='project' AND slug='cafe-neon-concept');

INSERT INTO content_items(id,type,slug,status,draft_json,published_json,sort_order) SELECT 'project-marquee-entrance-concept','project','marquee-entrance-concept','published','{"title":"Marquee-Style Restaurant Entrance","intro":"Visible light points and dimensional letters give the entrance a distinctive evening character.","product":"specialty-signs","setting":"Dining","image":"/assets/products-v2/marquee-scene.webp","imageAlt":"Marquee-Style Restaurant Entrance — AI-generated design concept","imageKind":"concept","sourceNote":"AI-generated design concept; not a delivered client installation. Existing licensed asset provenance is recorded in the homepage/product asset ledgers.","indexable":false,"sort":5,"gallery":[{"src":"/assets/supplier/exposed-light-letter.webp","alt":"Letter sample showing visible light points","caption":"Fabrication sample · Exposed light-point lettering"},{"src":"/assets/supplier/letter-return-detail.webp","alt":"Metal return and face on a dimensional letter","caption":"Construction detail · Formed return and visible surface"}],"body":"## The Design Brief\n\nGive a restaurant or entertainment entrance a strong evening identity. This concept combines deep dimensional lettering with visible points of light, using the entrance architecture as a frame.\n\n## Design Decisions\n\n### Light points as part of the identity\n\nThe visible lighting rhythm gives the letters their character. Point size, spacing and the artwork need to be designed together.\n\n### Depth and finish add presence\n\nThe metal appearance and returns create a substantial silhouette in daylight as well as at night. Confirm the actual material and finish separately.\n\n### Coordinate with the entrance\n\nReview the wall space above the door, adjacent light fittings and the sign viewing angle before setting the final layout.\n\n## Proposed Configuration\n\n**Application:** Restaurant, bar or entertainment entrance\n\n**Letter construction:** Built-up dimensional letters; construction developed around the design\n\n**Lighting direction:** Exposed light points; component type and spacing to be specified\n\n**Finish:** Painted or metal appearance by approved reference\n\n**Mounting approach:** Individual or supported mounting, reviewed against the structure\n\n**Size & scope:** Overall width, return depth, light-point arrangement and access confirmed before quoting\n\n## Prepare Your Installation\n\n### Check fixing and access\n\nIdentify the wall construction and how the installer will reach and maintain the sign.\n\n### Review exposure and components\n\nTell us the destination and whether the sign is exposed to rain. Component selection and required documentation must suit the agreed configuration.\n\n### Confirm the light pattern\n\nApprove a drawing showing letter profiles and light-point positions, together with the finish and cable arrangement.\n\n## Make It Your Own\n\nChange the lettering, finish and light-point arrangement. The design can be adapted for a smaller interior feature or a larger entrance identity.\n\nInclude any dimming, replacement-access or event-use requirements at the enquiry stage so they can be reviewed in the quotation."}','{"title":"Marquee-Style Restaurant Entrance","intro":"Visible light points and dimensional letters give the entrance a distinctive evening character.","product":"specialty-signs","setting":"Dining","image":"/assets/products-v2/marquee-scene.webp","imageAlt":"Marquee-Style Restaurant Entrance — AI-generated design concept","imageKind":"concept","sourceNote":"AI-generated design concept; not a delivered client installation. Existing licensed asset provenance is recorded in the homepage/product asset ledgers.","indexable":false,"sort":5,"gallery":[{"src":"/assets/supplier/exposed-light-letter.webp","alt":"Letter sample showing visible light points","caption":"Fabrication sample · Exposed light-point lettering"},{"src":"/assets/supplier/letter-return-detail.webp","alt":"Metal return and face on a dimensional letter","caption":"Construction detail · Formed return and visible surface"}],"body":"## The Design Brief\n\nGive a restaurant or entertainment entrance a strong evening identity. This concept combines deep dimensional lettering with visible points of light, using the entrance architecture as a frame.\n\n## Design Decisions\n\n### Light points as part of the identity\n\nThe visible lighting rhythm gives the letters their character. Point size, spacing and the artwork need to be designed together.\n\n### Depth and finish add presence\n\nThe metal appearance and returns create a substantial silhouette in daylight as well as at night. Confirm the actual material and finish separately.\n\n### Coordinate with the entrance\n\nReview the wall space above the door, adjacent light fittings and the sign viewing angle before setting the final layout.\n\n## Proposed Configuration\n\n**Application:** Restaurant, bar or entertainment entrance\n\n**Letter construction:** Built-up dimensional letters; construction developed around the design\n\n**Lighting direction:** Exposed light points; component type and spacing to be specified\n\n**Finish:** Painted or metal appearance by approved reference\n\n**Mounting approach:** Individual or supported mounting, reviewed against the structure\n\n**Size & scope:** Overall width, return depth, light-point arrangement and access confirmed before quoting\n\n## Prepare Your Installation\n\n### Check fixing and access\n\nIdentify the wall construction and how the installer will reach and maintain the sign.\n\n### Review exposure and components\n\nTell us the destination and whether the sign is exposed to rain. Component selection and required documentation must suit the agreed configuration.\n\n### Confirm the light pattern\n\nApprove a drawing showing letter profiles and light-point positions, together with the finish and cable arrangement.\n\n## Make It Your Own\n\nChange the lettering, finish and light-point arrangement. The design can be adapted for a smaller interior feature or a larger entrance identity.\n\nInclude any dimming, replacement-access or event-use requirements at the enquiry stage so they can be reviewed in the quotation."}',5 WHERE NOT EXISTS(SELECT 1 FROM content_items WHERE type='project' AND slug='marquee-entrance-concept');

