UPDATE content_items SET draft_json=json_set(draft_json,'$.body',json_extract('{"v":"## What to Look For\n\nThe face defines the visible outline; the return creates the side depth and holds the assembly together. Use this sample to discuss how your letter shape can be formed, finished and mounted.\n\n## Face & edge\n\nReview face material, edge treatment and how fine corners or narrow strokes will be made.\n\n## Return & assembly\n\nConfirm depth, seams, rear closure and the intended LED construction; an unlit sample does not establish the final lighting effect.\n\n## Plan Your Own Sign\n\nBring your artwork, approximate letter height and intended mounting surface. Identify any close viewing distance where edges and joins will be prominent."}','$.v')),published_json=json_set(published_json,'$.body',json_extract('{"v":"## What to Look For\n\nThe face defines the visible outline; the return creates the side depth and holds the assembly together. Use this sample to discuss how your letter shape can be formed, finished and mounted.\n\n## Face & edge\n\nReview face material, edge treatment and how fine corners or narrow strokes will be made.\n\n## Return & assembly\n\nConfirm depth, seams, rear closure and the intended LED construction; an unlit sample does not establish the final lighting effect.\n\n## Plan Your Own Sign\n\nBring your artwork, approximate letter height and intended mounting surface. Identify any close viewing distance where edges and joins will be prominent."}','$.v')),version=version+1 WHERE type='project' AND slug='front-lit-letter-reference' AND status='published' AND replace(json_extract(draft_json,'$.body'),char(13),'')=json_extract('{"v":"## What This Reference Shows\n\nUnlit face and metal return construction from supplier material. The photograph comes from our supplier''s brochure. It is not presented as a Custom Sign Forge customer project, and no client, delivered specification or installation location is claimed.\n\n## Details to Discuss for Your Own Sign\n\nUse the image to identify the outline, depth, finish or lighting effect that interests you. Send your own artwork, approximate dimensions, intended use and delivery country so the construction can be reviewed for your requirements.\n\n## Before Approving Production\n\nConfirm the materials, dimensions, finish, lighting where relevant, fixing arrangement and supplied parts in the quotation and approved specification. Any required sample, document, packing or local installation support must be agreed separately."}','$.v') AND replace(json_extract(published_json,'$.body'),char(13),'')=json_extract('{"v":"## What This Reference Shows\n\nUnlit face and metal return construction from supplier material. The photograph comes from our supplier''s brochure. It is not presented as a Custom Sign Forge customer project, and no client, delivered specification or installation location is claimed.\n\n## Details to Discuss for Your Own Sign\n\nUse the image to identify the outline, depth, finish or lighting effect that interests you. Send your own artwork, approximate dimensions, intended use and delivery country so the construction can be reviewed for your requirements.\n\n## Before Approving Production\n\nConfirm the materials, dimensions, finish, lighting where relevant, fixing arrangement and supplied parts in the quotation and approved specification. Any required sample, document, packing or local installation support must be agreed separately."}','$.v');
