UPDATE content_items SET draft_json=json_set(draft_json,'$.body',json_extract('{"v":"## What to Look For\n\nAn opaque face keeps the light behind the letter. This sample helps you compare the dimensional metal body and illuminated backing before reviewing the halo on your own wall.\n\n## Face & side finish\n\nSpecify the visible metal finish on both the face and returns. Review a finish reference if colour and brushing direction matter.\n\n## Halo & clearance\n\nDiscuss the rear lighting, wall stand-off and cable exit together. Wall texture and the spacing behind the sign affect the light spread.\n\n## Plan Your Own Sign\n\nSend a wall photo, overall logo width and preferred light colour. Agree driver access, mounting positions and a visual approval method."}','$.v')),published_json=json_set(published_json,'$.body',json_extract('{"v":"## What to Look For\n\nAn opaque face keeps the light behind the letter. This sample helps you compare the dimensional metal body and illuminated backing before reviewing the halo on your own wall.\n\n## Face & side finish\n\nSpecify the visible metal finish on both the face and returns. Review a finish reference if colour and brushing direction matter.\n\n## Halo & clearance\n\nDiscuss the rear lighting, wall stand-off and cable exit together. Wall texture and the spacing behind the sign affect the light spread.\n\n## Plan Your Own Sign\n\nSend a wall photo, overall logo width and preferred light colour. Agree driver access, mounting positions and a visual approval method."}','$.v')),version=version+1 WHERE type='project' AND slug='halo-letter-reference' AND status='published' AND replace(json_extract(draft_json,'$.body'),char(13),'')=json_extract('{"v":"## What This Reference Shows\n\nRear illumination on individual letter samples from supplier material. The photograph comes from our supplier''s brochure. It is not presented as a Custom Sign Forge customer project, and no client, delivered specification or installation location is claimed.\n\n## Details to Discuss for Your Own Sign\n\nUse the image to identify the outline, depth, finish or lighting effect that interests you. Send your own artwork, approximate dimensions, intended use and delivery country so the construction can be reviewed for your requirements.\n\n## Before Approving Production\n\nConfirm the materials, dimensions, finish, lighting where relevant, fixing arrangement and supplied parts in the quotation and approved specification. Any required sample, document, packing or local installation support must be agreed separately."}','$.v') AND replace(json_extract(published_json,'$.body'),char(13),'')=json_extract('{"v":"## What This Reference Shows\n\nRear illumination on individual letter samples from supplier material. The photograph comes from our supplier''s brochure. It is not presented as a Custom Sign Forge customer project, and no client, delivered specification or installation location is claimed.\n\n## Details to Discuss for Your Own Sign\n\nUse the image to identify the outline, depth, finish or lighting effect that interests you. Send your own artwork, approximate dimensions, intended use and delivery country so the construction can be reviewed for your requirements.\n\n## Before Approving Production\n\nConfirm the materials, dimensions, finish, lighting where relevant, fixing arrangement and supplied parts in the quotation and approved specification. Any required sample, document, packing or local installation support must be agreed separately."}','$.v');
