UPDATE content_items SET draft_json=json_set(draft_json,'$.body',json_extract('{"v":"## What to Look For\n\nDimensional metal lettering can use material and shadow as the main visual effect. This sample shows the surface and side depth of formed letters, ready for a discussion of your own artwork.\n\n## Surface direction\n\nCompare brushing, sheen and colour under the lighting where the sign will be installed. Confirm whether visible sides require the same finish.\n\n## Depth & fixing\n\nSelect cut or built-up construction according to the artwork and required depth. Review studs, backing and the wall substrate with your installer.\n\n## Plan Your Own Sign\n\nShare logo files, approximate dimensions and indoor or outdoor exposure. For exposed sites, identify the local environment before selecting a metal grade and finish."}','$.v')),published_json=json_set(published_json,'$.body',json_extract('{"v":"## What to Look For\n\nDimensional metal lettering can use material and shadow as the main visual effect. This sample shows the surface and side depth of formed letters, ready for a discussion of your own artwork.\n\n## Surface direction\n\nCompare brushing, sheen and colour under the lighting where the sign will be installed. Confirm whether visible sides require the same finish.\n\n## Depth & fixing\n\nSelect cut or built-up construction according to the artwork and required depth. Review studs, backing and the wall substrate with your installer.\n\n## Plan Your Own Sign\n\nShare logo files, approximate dimensions and indoor or outdoor exposure. For exposed sites, identify the local environment before selecting a metal grade and finish."}','$.v')),version=version+1 WHERE type='project' AND slug='metal-letter-reference' AND status='published' AND replace(json_extract(draft_json,'$.body'),char(13),'')=json_extract('{"v":"## What This Reference Shows\n\nSurface and side depth on formed letters from supplier material. The photograph comes from our supplier''s brochure. It 