UPDATE content_items SET draft_json=json_set(draft_json,'$.body',json_extract('{"v":"## What to Look For\n\nLayering creates combinations of colour and transparency that a single flat face cannot show. Use this sample to discuss the outline, visible edge and assembled thickness of your logo.\n\n## Colour & transparency\n\nIdentify which layers are opaque, translucent or clear. Screen colours alone do not establish a finished material colour.\n\n## Layer alignment\n\nReview the registration of each cut shape, the exposed edge finish and how the assembly attaches to the wall or backing.\n\n## Plan Your Own Sign\n\nSend vector artwork and a side-view reference if the depth matters. Specify whether the sign is unlit or illuminated, and confirm the required fixing method."}','$.v')),published_json=json_set(published_json,'$.body',json_extract('{"v":"## What to Look For\n\nLayering creates combinations of colour and transparency that a single flat face cannot show. Use this sample to discuss the outline, visible edge and assembled thickness of your logo.\n\n## Colour & transparency\n\nIdentify which layers are opaque, translucent or clear. Screen colours alone do not establish a finished material colour.\n\n## Layer alignment\n\nReview the registration of each cut shape, the exposed edge finish and how the assembly attaches to the wall or backing.\n\n## Plan Your Own Sign\n\nSend vector artwork and a side-view reference if the depth matters. Specify whether the sign is unlit or illuminated, and confirm the required fixing method."}','$.v')),version=version+1 WHERE type='project' AND slug='acrylic-letter-reference' AND status='published' AND replace(json_extract(draft_json,'$.body'),char(13),'')=json_extract('{"v":"## What This Reference Shows\n\nColoured and clear layers from supplier material. The photograph comes from our supplier''s brochure. It is not presented as a Custom Sign Forge customer project, and no client, delivered specification or installation location is claimed.\n\n## Details to Discuss for Your Own Sign\n\nUse the image to identify the outline, depth, finish or lighting effect that interests you. Send your own artwork, approximate dimensions, intended use and delivery country so the construction can be reviewed for your requirements.\n\n## Before Approving Production\n\nConfirm the materials, dimensions, finish, lighting where relevant, fixing arrangement and supplied parts in the quotation and approved specification. Any required sample, document, packing or local installation support must be agreed separately."}','$.v') AND replace(json_extract(published_json,'$.body'),char(13),'')=json_extract('{"v":"## What This Reference Shows\n\nColoured and clear layers from supplier material. The photograph comes from our supplier''s brochure. It is not presented as a Custom Sign Forge customer project, and no client, delivered specification or installation location is claimed.\n\n## Details to Discuss for Your Own Sign\n\nUse the image to identify the outline, depth, finish or lighting effect that interests you. Send your own artwork, approximate dimensions, intended use and delivery country so the construction can be reviewed for your requirements.\n\n## Before Approving Production\n\nConfirm the materials, dimensions, finish, lighting where relevant, fixing arrangement and supplied parts in the quotation and approved specification. Any required sample, document, packing or local installation support must be agreed separately."}','$.v');
