UPDATE content_items SET draft_json=json_set(draft_json,'$.body',json_extract('{"v":"## What to Look For\n\nA neon-style construction follows the lines in your artwork. This sample is useful for discussing wording, curves, backing and the visibility of the illuminated stroke.\n\n## Artwork & line spacing\n\nTight bends, small characters and nearby strokes need to be reviewed at the actual sign size. Artwork may need adjustment for the selected system.\n\n## Backing & power\n\nDiscuss backing shape, fixing holes, light colour, cable exit and power-supply access as one assembly.\n\n## Plan Your Own Sign\n\nShare your wording or logo, overall size and whether the sign is for an interior or exterior location. Identify any dimming or control requirement before quoting."}','$.v')),published_json=json_set(published_json,'$.body',json_extract('{"v":"## What to Look For\n\nA neon-style construction follows the lines in your artwork. This sample is useful for discussing wording, curves, backing and the visibility of the illuminated stroke.\n\n## Artwork & line spacing\n\nTight bends, small characters and nearby strokes need to be reviewed at the actual sign size. Artwork may need adjustment for the selected system.\n\n## Backing & power\n\nDiscuss backing shape, fixing holes, light colour, cable exit and power-supply access as one assembly.\n\n## Plan Your Own Sign\n\nShare your wording or logo, overall size and whether the sign is for an interior or exterior location. Identify any dimming or control requirement before quoting."}','$.v')),version=version+1 WHERE type='project' AND slug='neon-style-reference' AND status='published' AND replace(json_extract(draft_json,'$.body'),char(13),'')=json_extract('{"v":"## What This Reference Shows\n\nIlluminated line graphics from supplier material. The photograph comes from our supplier''s brochure. It is not presented as a Custom Sign Forge customer project, and no client, delivered specification or installation location is claimed.\n\n## Details to Discuss for Your Own Sign\n\nUse the image to identify the outline, depth, finish or lighting effect that interests you. Send your own artwork, approximate dimensions, intended use and delivery country so the construction can be reviewed for your requirements.\n\n## Before Approving Production\n\nConfirm the materials, dimensions, finish, lighting where relevant, fixing arrangement and supplied parts in the quotation and approved specification. Any required sample, document, packing or local installation support must be agreed separately."}','$.v') AND replace(json_extract(published_json,'$.body'),char(13),'')=json_extract('{"v":"## What This Reference Shows\n\nIlluminated line graphics from supplier material. The photograph comes from our supplier''s brochure. It is not presented as a Custom Sign Forge customer project, and no client, delivered specification or installation location is claimed.\n\n## Details to Discuss for Your Own Sign\n\nUse the image to identify the outline, depth, finish or lighting effect that interests you. Send your own artwork, approximate dimensions, intended use and delivery country so the construction can be reviewed for your requirements.\n\n## Before Approving Production\n\nConfirm the materials, dimensions, finish, lighting where relevant, fixing arrangement and supplied parts in the quotation and approved specification. Any required sample, document, packing or local installation support must be agreed separately."}','$.v');
